                localStorage.setItem('pcv-console-fit', next.fit);
            if (VM_CONSOLE_FRAME_SIZES.includes(next.size))
                localStorage.setItem('pcv-console-size', next.size);
            const fps = Number(next.fps);
            if (VM_CONSOLE_FRAME_FPS.includes(fps))
                localStorage.setItem('pcv-console-fps', String(fps));
