            return `${control.error.code}: ${control.error.message}`;
        if (running)
            return t('vm.console.status.streaming', { size, fps });
        const vmState = String(vm?.state || vm?.status || '').toLowerCase();
        if (vmState === 'running')
            return t('vm.console.status.paused');
